import itertools

def get_max_independent_set_size(n, edges):
    # Using a simple backtracking or brute force to find max independent set
    # Since n=20, 2^20 is ~1 million, which is manageable.
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    max_is = 0
    for i in range(1 << n):
        subset = [j for j in range(n) if (i & (1 << j))]
        is_independent = True
        for u, v in itertools.combinations(subset, 2):
            if v in adj[u]:
                is_independent = False
                break
        if is_independent:
            max_is = max(max_is, len(subset))
    return max_is

def get_node_connectivity(n, edges):
    # Node connectivity is the minimum number of nodes to remove to disconnect the graph
    # or make it trivial.
    # For n=20, we can use Menger's theorem or just check all subsets of size < 4.
    # Actually, checking if it's 4-connected is easier.
    # A graph is k-connected if it has at least k+1 vertices and removing any k-1 vertices leaves it connected.

    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check if removing any 3 nodes leaves it connected
    for nodes_to_remove in itertools.combinations(range(n), 3):
        remaining_nodes = [i for i in range(n) if i not in nodes_to_remove]
        if not remaining_nodes: continue

        # Check connectivity of remaining_nodes
        start_node = remaining_nodes[0]
        visited = {start_node}
        queue = [start_node]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in nodes_to_remove and v not in visited:
                    visited.add(v)
                    queue.append(v)

        if len(visited) != len(remaining_nodes):
            return False
    return True

