    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Bron-Kerbosch algorithm to find max independent set
    # Max independent set of G is max clique of complement G
    # Complement edges:
    comp_adj = [set() for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if j not in adj[i]:
                comp_adj[i].add(j)
                comp_adj[j].add(i)

    def bron_kerbosch(r, p, x):
        if not p and not x:
            return len(r)

        max_clique = 0
        for v in list(p):
            max_clique = max(max_clique, bron_kerbosch(r | {v}, p & comp_adj[v], x & comp_adj[v]))
            p.remove(v)
            x.add(v)
        return max_clique

    return bron_kerbosch(set(), set(range(n)), set())

